const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)e.target.classList.add('show')}),{threshold:.13});document.querySelectorAll('.reveal').forEach(el=>io.observe(el));document.querySelector('#copy').addEventListener('click',async e=>{await navigator.clipboard.writeText('请替换为你的真实联系方式');e.currentTarget.textContent='已复制（待替换）';setTimeout(()=>e.currentTarget.textContent='复制联系方式 →',1600)});
